import React, { useState, useEffect } from "react";
import { Select, Form, Input, Button, Col, Row, Spin, message } from 'antd';
import { RUTA } from "../../route";
import axios from "axios";

import './Renovaciones.css';

const { Option } = Select;

export const RenovacionesComponent = () => {
    const [renovacion, setRenovacion] = useState([]);
    const [selectedClient, setSelectedClient] = useState('');
    const [datos, setDatos] = useState(null);
    const [loading, setLoading]= useState(false)
    const [form] = Form.useForm();
   


    const onFinish = (values) => {
        handleAdd(values);
    };

    const fetchData = async () => {
        try {
            const response = await axios.get(`${RUTA}/renovacionList`);
            setRenovacion(response.data.Data);
        } catch (error) {
            console.error('Error al generar la lista de renovaciones', error);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const handleCustomerChange = async (value) => {
        setLoading(true)
        try {
            setSelectedClient(value);
            console.log('Valor del cliente seleccionado:', value);
            const response = await axios.get(`${RUTA}/getClientInfo/${value}`);
            setDatos(response.data.Data[0]); 
        } catch (error) {
            console.error('Error al cargar datos', error);
        }finally{
            setLoading(false);
        }
    };


    useEffect(() =>{
        if(datos){
            form.setFieldsValue(datos)
        }
    }, [datos, form]);

    const handleAdd= async(values) => {
        setLoading(true);
        try{
          console.log('valores a enviar al editar', values)
          const response = await axios.put(`${RUTA}/clientInformation/${values.nombre}`, values);
          console.log(response)
          if(response.status === 200){
            const messageSuccess= response.data.message;
            message.success(messageSuccess);
          }
        }catch(error){
            console.error('Error al editar los datos', error);
        }finally{
            setLoading(false)
        }
    }

    

    return (
        <>
            <h1>Renovaciones</h1>

            <div>
                <Select
                    placeholder='Selecciona un cliente'
                    onChange={handleCustomerChange}
                    value={selectedClient}
                    showSearch
                    className="select"
                >
                    {renovacion.map((item) => (
                        <Option value={item.nombre}>
                            {item.nombre}
                        </Option>
                    ))}
                </Select>
            </div>

            {loading ? (
                <Spin size="large" style={{ display: 'block', margin: '0 auto' }} />
            ):
              datos? (
               <>
                <Form
                    form={form}
                    onFinish={onFinish}
                    layout="vertical"
                    initialValues={datos}
                    onSubmit={handleAdd}
                >
                    <Row gutter={16}>
                        <Col span={8}>
                            <Form.Item label="Nombre" name="nombre">
                                <Input disabled/>
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Dirección" name="direccion">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Teléfono" name="telefono">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Colonia" name="colonia">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Puesto" name="puesto">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Empresa" name="empresa">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Antigüedad" name="antiguedad">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Dirección de la Empresa" name="sueldo_in">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Sueldo Actual" name="sueldo_final">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Monto del Préstamo" name="monto">
                                <Input disabled/>
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Fecha de Inicio" name="fechaInicio">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Frecuencia de Pago" name="frecuenciaPago">
                                <Select>
                                    <Option value="Quincenal">Quincenal</Option>
                                    <Option value="Mensual">Mensual</Option>
                                </Select>
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Plazo" name="plazo">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Estado" name="estado">
                                <Select disabled>
                                    <Option value="Aprobado">Aprobado</Option>
                                    <Option value="Rechazado">Rechazado</Option>
                                </Select>
                            </Form.Item>
                        </Col>

                        
                        <Col span={8}>
                            <Form.Item label="Redes Sociales" name="redes_sociales">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Referencias" name="referencia">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Dirección de Referencias" name="referencia_dom">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Teléfono de Referencias" name="referencia_cel">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Parentesco" name="parentezco">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Número de Cédula" name="cedulaNumero">
                                <Input />
                            </Form.Item>
                        </Col>

                        


                        <Col span={8}>
                            <Form.Item label="Red Social Referencia" name="redSocialRef">
                                <Input />
                            </Form.Item>
                        </Col>

                        <Col span={8}>
                            <Form.Item label="Barrio de Referencia" name="barrio_ref">
                                <Input />
                            </Form.Item>
                        </Col>
                    </Row>

                   
                        
                   

                    <Form.Item>
                        <Button type="primary" htmlType="submit" loading={loading}>
                            Editar Datos 
                        </Button>
                    </Form.Item>
                </Form>


                
               

                        
                
             </>
            ): (
                <div className="warning"> Cliente no se encuentra registrado</div>
            )}
        </>
    );
};
